CREATE OR REPLACE FUNCTION private.academy_catalog() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'title',title,'slug',slug,'description',description,'short_description',short_description,'product_type',product_type,'status',status,'education_meta',education_meta,'thumbnail_url',thumbnail_url) ORDER BY product_type,title),'[]') FROM public.products WHERE product_type IN('ebook','curso') AND education_meta<>'{}'::jsonb AND status<>'archived'; $$;
REVOKE ALL ON FUNCTION private.academy_catalog() FROM PUBLIC; GRANT EXECUTE ON FUNCTION private.academy_catalog() TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.academy_catalog() RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT private.academy_catalog(); $$;
REVOKE ALL ON FUNCTION public.academy_catalog() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.academy_catalog() TO anon,authenticated;
CREATE OR REPLACE FUNCTION private.academy_lessons_for_course(_product uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT(private.has_role(auth.uid(),'admin') OR private.has_product_access(auth.uid(),_product)) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',l.id,'title',l.title,'module_id',m.id,'module_title',m.title,'module_order',m.order_index,'order_index',l.order_index,'minutes',l.minutes,'published',l.published,'objectives',l.objectives,'references_text',l.references_text,'body',CASE WHEN private.academy_can_study(l.id) OR private.has_role(auth.uid(),'admin') THEN l.body ELSE '' END,'available',private.academy_can_study(l.id)) ORDER BY m.order_index,l.order_index),'[]') FROM public.academy_lessons l JOIN public.product_modules m ON m.id=l.module_id WHERE m.product_id=_product AND (l.published OR private.has_role(auth.uid(),'admin'))); END; $$;
REVOKE ALL ON FUNCTION private.academy_lessons_for_course(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION private.academy_lessons_for_course(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.academy_lessons_for_course(_product uuid) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT private.academy_lessons_for_course(_product); $$;
REVOKE ALL ON FUNCTION public.academy_lessons_for_course(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.academy_lessons_for_course(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION private.academy_can_study(_lesson uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.academy_lessons l JOIN public.product_modules m ON m.id=l.module_id JOIN public.products p ON p.id=m.product_id WHERE l.id=_lesson AND l.published AND (private.has_role(auth.uid(),'admin') OR (p.status='active' AND private.has_product_access(auth.uid(),p.id))) AND NOT EXISTS(SELECT 1 FROM public.academy_lessons prev JOIN public.product_modules pm ON pm.id=prev.module_id WHERE pm.product_id=m.product_id AND prev.published AND (pm.order_index,prev.order_index)<(m.order_index,l.order_index) AND NOT EXISTS(SELECT 1 FROM public.academy_progress pr WHERE pr.user_id=auth.uid() AND pr.lesson_id=prev.id))); $$;
CREATE POLICY lessons_restrict_sequence ON public.academy_lessons AS RESTRICTIVE FOR SELECT TO authenticated USING(private.has_role(auth.uid(),'admin') OR private.academy_can_study(id));